    "stem": "编写程序，提示用户输入两个整数，然后显示两个整数的和，如果输入的数据不正确，则显示相应的信息。",
    "answer": "# 提示用户输入两个整数\nnum1 = input(\"请输入第一个整数: \")\nnum2 = input(\"请输入第二个整数: \")\n# 检查输入是否都是整数\ntry:\n    int1 = int(num1)\n    int2 = int(num2)\nexcept ValueError:\n    print(\"输入的数据不是整数，请重新输入。\")\nelse:\n    # 显示两个整数的和\n    sum = int1 + int2\n    print(\"两数之和为:\", sum)"
