    "answer": "import random\nrandom_numbers = []\nwhile True:\n    random_number = random.randint(1, 1000)\n    if random_number % 2 == 0:\n        random_numbers.append(random_number)\n    if len(random_numbers)==20:\n        break\nprint(random_numbers)"
