    "answer": "安装模块：pip install flask\n参考程序1：返回字符串\n# 导入Flask模块\nfrom flask import Flask\n# 创建一个Flask应用\napp = Flask(__name__)\n# 定义一个路由/，接口返回‘hello world’\n@app.route('/')\ndef index():\n    return 'hello world'\n# 运行程序\nif __name__ == '__main__':\napp.run()\n参考程序2：返回html样式\nfrom flask import Flask\napp = Flask(__name__)\n@app.route('/')\ndef index():\n    return '<h3>welcome to my Flask!</h3><hr><p style=\"color:red\">Hello World</p>'\nif __name__ == '__main__':\napp.run()\n    参考程序3：传入html文件\nfrom flask import Flask, render_template\napp = Flask(__name__)\n@app.route('/')\ndef index():\n    return render_template('index.html')\nif __name__ == '__main__':\napp.run()\nhtml文件：index.html\n# index.html\n<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"UTF-8\">\n    <title>My Test</title>\n</head>\n<body>\n    <h3>welcome to my Flask!</h3>\n    <hr>\n    <p style=\"color:red\">Hello World</p>\n    <p>采用render_temple模版方法展示页面</p>\n</body>\n</html>"
